import { AbstractInputField } from '../shared/abstract-input-field';
import { createElement, dynamicAttr, elementIsDisabled, replace, updateDynamicAttribute, getClosest, dynamicProperty, updateDynamicPropertyOnChildren, updateDynamicAttributeOnChildren } from '../shared/dom-manipulation';
import { getRequiredOnlyValidators } from '../shared/validation-engine/validate-engine';
import './neon-checkbox-field.scss';
export class NeonCheckboxField extends AbstractInputField {
    static get observedAttributes() {
        return super.observedAttributes.concat([
            'data-control-layout',
            'data-parent-checkbox-behavior',
            'data-size'
        ]);
    }
    set options(value) {
        //We need to check to see if the new array of options has the same value as
        //What's currently here.  If everything is the same, then there will be no reason to redraw the checkboxes.
        let isDifferent = false;
        if (this.options != null && value != null && this.options.length === value.length) {
            for (let i = 0; i < this.options.length; i++) {
                const newCheckOption = value[i];
                const oldCheckOption = this.options[i];
                if (oldCheckOption.id !== newCheckOption.id ||
                    oldCheckOption.labelText !== newCheckOption.labelText ||
                    oldCheckOption.name !== newCheckOption.name ||
                    oldCheckOption.disabled !== newCheckOption.disabled ||
                    oldCheckOption.helperText !== newCheckOption.helperText ||
                    oldCheckOption.checkType !== newCheckOption.checkType ||
                    oldCheckOption.isIndented !== newCheckOption.isIndented) {
                    isDifferent = true;
                    break; //Once we know it's different, we don't have to keep checking
                }
            }
        }
        else {
            isDifferent = true;
        }
        this._options = value;
        this.buildCheckboxOptionMaps();
        if (isDifferent) {
            this.redrawCheckboxes();
            if (this.runValidationOnceOptionsSet) {
                this.validateWidget();
                this.runValidationOnceOptionsSet = false;
            }
        }
    }
    get options() {
        return this._options;
    }
    constructor() {
        super();
        this.widgetTag = 'neon-checkbox-field';
        this.isUsesLabel = false;
        // This is set to true because the legend is used as the label for the field.
        this.isUsesLegend = true;
        // Prevents race condition to prevent the validation appearing
        // after modelValue getting set before the options are set.
        this.runValidationOnceOptionsSet = false;
        //key: parentId, value: Array of children
        this.optionsParentToChildrenMap = {};
        //key: childId, value: parent
        this.optionsChildToParentMap = {};
    }
    buildCheckboxOptionMaps() {
        this.optionsParentToChildrenMap = {};
        this.optionsChildToParentMap = {};
        if (this.options == null) {
            return;
        }
        let currentParent;
        let currentChildren = [];
        //Loop through and find all of the children for the parent.
        for (let i = 0; i < this.options.length; i++) {
            const option = this.options[i];
            if (option.isIndented === true) {
                if (currentParent != null) {
                    currentChildren.push(option);
                }
            }
            else {
                if (currentParent != null && currentChildren.length > 0) {
                    //We must be switching things up.  Save things off to the member properties.
                    //And then clear out the local variables.
                    this.optionsParentToChildrenMap[currentParent.id] = currentChildren;
                    for (const child of currentChildren) {
                        this.optionsChildToParentMap[child.id] = currentParent;
                    }
                    currentParent = undefined;
                    currentChildren = [];
                }
                if (i + 1 < this.options.length && this.options[i + 1].isIndented === true) {
                    //We know that option is not indented here.
                    //We know that the next option is indented
                    currentParent = option;
                    currentChildren = [];
                }
            }
        }
        if (currentParent != null && currentChildren.length > 0) {
            //We must be switching things up.  Save things off to the member properties.
            //And then clear out the local variables.
            this.optionsParentToChildrenMap[currentParent.id] = currentChildren;
            for (const child of currentChildren) {
                this.optionsChildToParentMap[child.id] = currentParent;
            }
        }
    }
    getChildrenOfCheckboxOption(option) {
        return this.optionsParentToChildrenMap[option.id] || [];
    }
    getParentOfCheckboxOption(option) {
        return this.optionsChildToParentMap[option.id];
    }
    isParentCheckboxOption(option) {
        return this.optionsParentToChildrenMap[option.id] != null;
    }
    isChildCheckboxOption(option) {
        //It's a child if it has a parent.
        return this.getParentOfCheckboxOption(option) != null;
    }
    isSelectAllMode() {
        return this.getAttribute('data-parent-checkbox-behavior') !== 'disable-all';
    }
    generateValidationRules() {
        this.validators = getRequiredOnlyValidators(this.getAttribute('data-is-required') === 'true');
        this.addCustomValidateToValidators();
    }
    renderInputElement() {
        return createElement('div');
    }
    validateModelValueType(modelValue) {
        if ((Array.isArray(modelValue) && modelValue.length > 0) || modelValue == null) {
            return modelValue;
        }
        return undefined;
    }
    setModelValue(modelValue, skip) {
        //If someone is trying to set the modelValue to null, when they get the modelValue back it's
        //going to be undefined which means null and undefined are equal values for this widget.
        //This case will then say, "No change happened" if the passed in value is null and the current modelValue is already
        //undefined. This was added in PDS-2190 to allow this widget to be compatible with using Polymer which likes to set
        //things to null rather than undefined.
        if (this.modelValue == null && modelValue == null) {
            return false;
        }
        if (modelValue !== this._modelValue) {
            if (modelValue instanceof Array) {
                this._modelValue = [...modelValue];
                if (skip !== true) {
                    this.setValue(JSON.stringify(this._modelValue), true);
                }
            }
            else {
                delete this._modelValue;
                if (skip !== true) {
                    this.setValue('');
                }
            }
            return true;
        }
        return false;
    }
    setValue(value, skip) {
        let values;
        if (value != null) {
            try {
                values = JSON.parse(value);
            }
            catch ( /* no-op */_a) { /* no-op */ }
        }
        const inputEls = this.querySelectorAll('neon-2_20_1-checkbox-single');
        for (let i = 0; i < inputEls.length; i++) {
            const checkboxSingle = inputEls[i];
            checkboxSingle.value = this.calculateValue(checkboxSingle.neonCheckboxOption, values);
        }
        if (skip !== true) {
            this.setModelValue(values, true);
        }
    }
    get value() {
        const values = [];
        const result = this.querySelectorAll('neon-2_20_1-checkbox-single');
        for (const checkbox of Array.from(result)) {
            const excludeCheckbox = this.isSelectAllMode() && checkbox.getAttribute('data-is-parent') === 'true';
            if (!excludeCheckbox && checkbox.value === true) {
                values.push(checkbox.getAttribute('name'));
            }
        }
        if (values.length === 0) {
            return '';
        }
        return JSON.stringify(values);
    }
    get modelValue() {
        return this._modelValue;
    }
    set modelValue(value) {
        value = this.validateModelValueType(value);
        const modelValueChanged = this.setModelValue(value);
        if (modelValueChanged) {
            if (this.options != null) {
                this.validateWidget();
                if (this.isValid) {
                    this.setError('');
                }
            }
            else {
                //Defer validation until the options have been set.
                this.runValidationOnceOptionsSet = true;
            }
        }
        this.setReadonlyText();
    }
    render() {
        if (this.getAttribute('data-is-read-only') === 'true') {
            return createElement('div', {
                attrs: {
                    class: 'neon-checkbox-field-read-only-fieldset'
                }
            }, ...this.renderFieldLabels(), this.renderCheckboxes());
        }
        return createElement('fieldset', {}, ...this.renderFieldLabels(), this.renderCheckboxes(), this.errorElement, //Note: The order here is expected in redrawCheckboxes()
        this.successElement);
    }
    //Calculates the value that should be passed along to the neon-2_20_1-checkbox-single
    calculateValue(option, values) {
        if (values == null) {
            return false;
        }
        if (this.isSelectAllMode() && this.isParentCheckboxOption(option)) {
            //First get all of the non-disabled checkbox options.
            const childOptions = this.getChildrenOfCheckboxOption(option).filter((option) => {
                return option.disabled !== true;
            });
            //Of those options, get the ones that are in the values array.
            const selectedOptions = childOptions.filter((childOption) => {
                return values.indexOf(childOption.name) >= 0;
            });
            //Now compare the two arrays to decide which result to give.
            if (selectedOptions.length === 0) {
                return false;
            }
            else if (selectedOptions.length === childOptions.length) {
                return true;
            }
            else {
                return 'indeterminate';
            }
        }
        else {
            return values.indexOf(option.name) >= 0;
        }
    }
    renderCheckboxes() {
        //Make sure we start with an array of some kind, even if empty.
        const options = this.options || [];
        return createElement('div', {
            attrs: {
                class: dynamicAttr(() => {
                    let inputsContainerClasses = 'neon-checkbox-field-inputs neon-input-field-first';
                    if (this.getAttribute('data-control-layout') === 'row') {
                        inputsContainerClasses += ' neon-checkbox-field-row-layout';
                    }
                    return inputsContainerClasses;
                })
            }
        }, ...options.map((option) => {
            return createElement('neon-2_20_1-checkbox-single', {
                attrs: {
                    id: option.id,
                    'data-label-text': option.labelText,
                    name: option.name,
                    disabled: dynamicAttr(() => {
                        if (elementIsDisabled(this)) {
                            //If the neon-checkbox-field is disabled, ALL checkboxes are disabled
                            //regardless of disabled status in the option.
                            return 'true';
                        }
                        else {
                            const disabledStatus = (option.disabled != null ? String(option.disabled) : undefined);
                            if (disabledStatus != null) {
                                //Regardless of whether we would normally compute the disabled status,
                                //If the status was set in the option, we use that.
                                return disabledStatus;
                            }
                            //If we get to this spot, it means that the disabled status has not been set in the option.
                            //In disable-all mode, we calculate the disabled status for child items so we will do that here.
                            //Otherwise the function will just return undefined, which is what disabledStatus is.
                            if (!this.isSelectAllMode()) {
                                //We are in disable-all mode.
                                //We have to use the parent of the option to know if it's truly a child option.
                                const parentOption = this.getParentOfCheckboxOption(option);
                                //parentOption != null means that it's a child item.
                                if (parentOption != null) {
                                    //If the modelValue == null, it means that nothing is selected, therefore the childOption should be disabled.
                                    //If this.modelValue.indexOf(parentOption.name) === -1, it means that the parent item has not been checked.
                                    return String(this.modelValue == null || this.modelValue.indexOf(parentOption.name) === -1);
                                }
                            }
                        }
                    }),
                    'data-helper-text': option.helperText,
                    'data-check-type': option.checkType,
                    'data-is-indented': (option.isIndented === true ? 'true' : 'false'),
                    'data-is-parent': String(this.isParentCheckboxOption(option)),
                    'data-size': dynamicAttr(() => { return this.getAttribute('data-size'); }),
                    'data-is-read-only': this.getAttribute('data-is-read-only'),
                },
                properties: {
                    neonCheckboxOption: option,
                    // value: this.modelValue == null ? false : this.modelValue.indexOf(option.name) >= 0
                    value: dynamicProperty(() => {
                        return this.calculateValue(option, this.modelValue);
                    })
                },
                listeners: {
                    change: (event) => {
                        if (this.isSelectAllMode() && this.isParentCheckboxOption(option)) {
                            const currentModelValue = this.modelValue || [];
                            if (event.target.getValue() === true) {
                                //check all of the children
                                const newModelValue = currentModelValue.slice(); //Clones the array
                                for (const childOption of this.getChildrenOfCheckboxOption(option)) {
                                    // Only add the childOption to the model value if
                                    // 1) The option isn't disabled
                                    // 2) The option isn't already in the modelValue (We don't want duplicates).
                                    if (childOption.disabled !== true && !currentModelValue.includes(childOption.name)) {
                                        newModelValue.push(childOption.name);
                                    }
                                }
                                this.setModelValue(newModelValue);
                            }
                            else {
                                //Uncheck all of the children
                                const checkboxChildren = this.getChildrenOfCheckboxOption(option);
                                const newModelValue = currentModelValue.filter((selectedOption) => {
                                    //We filter out anything we find.
                                    return checkboxChildren.find((childOption) => {
                                        //If the currentModelValue is for the child, then we want to remove the selectedOption from
                                        //the modelValue.  In other words, returning true here removes the element from the currentModelValue.
                                        //Returning false here will keep the option in the modelValue.
                                        //Note: Now it can only return true if the option is not disabled.
                                        return childOption.disabled !== true && childOption.name === selectedOption;
                                    }) == null;
                                });
                                this.setModelValue(newModelValue);
                            }
                        }
                        //Standard behavior here
                        this.errorPresentWhenBlurOccurred = true;
                        this.inputChange();
                        if (this.isSelectAllMode() && this.isChildCheckboxOption(option)) {
                            //This will update any parent checkboxes
                            updateDynamicPropertyOnChildren(this, 'value');
                        }
                        if (!this.isSelectAllMode()) {
                            updateDynamicAttributeOnChildren(this, 'disabled');
                        }
                    },
                    blur: (event) => {
                        //In a set timeout so that the new active element will be set.
                        setTimeout(() => {
                            //If the activeElement isn't inside of this widget, then run the focusLost function.
                            if (getClosest(document.activeElement, `[${this.widgetTag}]`) !== this) {
                                this.focusLost(event);
                            }
                        });
                    }
                }
            });
        }));
    }
    redrawCheckboxes() {
        replace(this.renderCheckboxes(), this.querySelector('.neon-checkbox-field-inputs'));
    }
    attributeChanged(attribute, oldValue, newValue) {
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        super.attributeChanged(attribute, oldValue, newValue);
        switch (attribute) {
            case 'disabled':
                updateDynamicAttribute(this, 'disabled');
                break;
            case 'data-control-layout':
                updateDynamicAttribute(this, 'class');
                break;
            case 'data-parent-checkbox-behavior':
                updateDynamicAttributeOnChildren(this, 'disabled');
                updateDynamicPropertyOnChildren(this, 'value');
                break;
            case 'data-size':
                updateDynamicAttributeOnChildren(this, 'data-size');
                break;
            case 'data-is-read-only':
                this.isUsesLegend = newValue !== 'true';
                this.redraw();
                break;
        }
    }
}
